package web

// homeTemplate uses escaped Go templates and locally embedded browser assets.
const homeTemplate = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="csrf-token" content="{{.Token}}"><meta name="htmx-config" content='{"allowEval":false,"includeIndicatorStyles":false,"selfRequestsOnly":true}'>
<title>NetExplorer</title><link rel="icon" href="/static/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/static/bootstrap.min.css"><link rel="stylesheet" href="/static/app.css">
<script defer src="/static/htmx.min.js"></script><script defer src="/static/app.js"></script></head>
<body data-latest-scan="{{.LatestScan}}" data-latest-nmap="{{.LatestNmap}}" data-latest-check="{{.LatestCheck}}"><main class="workspace">
<header class="hero"><div class="hero-copy"><h1><img src="/static/favicon.svg" width="38" height="38" alt="">NetExplorer</h1></div>
<section class="scan-panel" aria-label="Scan controls"><div class="panel-heading"><div class="section-icon"><svg aria-hidden="true"><use href="/static/icons/devices.svg#search"></use></svg></div><div><span class="eyebrow">DISCOVERY</span><h2>Start a scan</h2></div></div>

<div class="system-strip"><div class="hero-tags"><span><i class="local-dot"></i> Local workspace</span><span>SSDP / UPnP · LAN hosts</span><span>v{{.Version}}</span></div><span class="tool-badge" title="{{.ARP.Version}} · {{.ARP.Mode}}">ARP · {{if .ARP.Available}}Installed{{else}}Not installed{{end}}</span>{{range .RuntimeTools}}<span class="tool-badge {{if not .Available}}tool-missing{{end}}" title="Executable availability only{{with .Path}} · {{.}}{{end}}">{{.Name}} · {{if .Available}}Installed{{else}}Missing{{end}}</span>{{end}}</div>{{if not .ARP.Available}}<details class="tool-status"><summary>Install ARP</summary><code>{{.ARP.Install}}</code></details>{{end}}<details class="tool-status"><summary>Vendor database <span id="vendor-health"></span></summary><p id="vendor-status">Loading database status…</p><button id="vendor-update" class="btn btn-sm btn-outline-primary" type="button">Update database</button><label><input id="vendor-auto" type="checkbox"> Update automatically every 30 days</label></details><form id="scan-form" class="command-panel"><div class="command-settings"><div class="command-field command-network"><label class="form-label" for="interface">Network interface</label><select id="interface" name="interface" class="form-select" required>
{{range .Interfaces}}{{if and .Up (not .Loopback) .IPv4}}<option value="{{.Name}}" {{if eq .Name $.DefaultInterface}}selected{{end}}>{{.Name}} — {{range .IPv4}}{{.}} {{end}}</option>{{end}}{{end}}</select></div>
<div class="command-field command-duration"><label for="seconds" class="form-label">Discovery window</label><div class="input-group"><input id="seconds" name="seconds" type="number" min="1" max="60" value="5" class="form-control" required><span class="input-group-text">s</span></div></div><div class="command-field command-interval"><label for="interval-seconds" class="form-label">Repeat interval</label><div class="input-group"><input id="interval-seconds" name="interval_seconds" type="number" min="10" max="3600" value="30" class="form-control" aria-label="Minimum discovery window interval in seconds"><span class="input-group-text">s</span></div></div></div>
<div class="command-row"><div class="command-options"><div class="scan-options"><div class="form-check"><input id="enrich" name="enrich" type="checkbox" checked class="form-check-input"><label for="enrich" class="form-check-label">Details <span class="info-icon" tabindex="0" role="img" aria-label="Read UPnP descriptions; up to 30 extra seconds" title="Read UPnP descriptions; up to 30 extra seconds">ⓘ</span></label></div></div>
<div class="scan-options host-discovery-option"><div class="form-check"><input id="all-hosts" name="all_hosts" type="checkbox" class="form-check-input" {{if .DiscoveryAvailable}}checked{{else}}disabled{{end}}><label for="all-hosts" class="form-check-label">LAN hosts <span class="info-icon" tabindex="0" role="img" aria-label="Discover responding hosts in this subnet via ARP, TCP and ICMP; up to 60 extra seconds" title="Discover responding hosts in this subnet via ARP, TCP and ICMP; up to 60 extra seconds">ⓘ</span></label></div>{{if not .DiscoveryAvailable}}<small>Requires Nmap or arp-scan</small>{{end}}</div>
<div class="scan-options monitor-options"><div class="form-check"><input id="auto-tcp" name="auto_tcp" type="checkbox" class="form-check-input" {{if .NmapAvailable}}checked{{else}}disabled{{end}}><label for="auto-tcp" class="form-check-label">Auto TCP <span class="info-icon" title="Inspect each new host once: common + notable ports. No automatic vulnerability checks.">ⓘ</span></label></div><div class="form-check"><input id="continuous" name="continuous" type="checkbox" class="form-check-input"><label for="continuous" class="form-check-label" title="Keep discovery running until Stop. Stop monitoring before manual service checks.">Continuous</label></div></div></div><div class="command-footer"><div class="authorization form-check"><input id="authorized" name="authorized" type="checkbox" required class="form-check-input"><label for="authorized" class="form-check-label" title="I own or am authorized to scan this LAN">Authorized</label></div>
<div class="scan-actions"><button id="start" {{if .Offline}}disabled{{end}} class="btn btn-primary" type="submit"><svg aria-hidden="true"><use href="/static/icons/devices.svg#search"></use></svg>Start</button><button id="pause" class="btn btn-outline-light" type="button" disabled title="Pause continuous discovery after active work finishes; preserve inventory">Pause</button><button id="cancel" class="btn btn-outline-danger" type="button" disabled>Stop</button></div></div></div></form>
<div class="scan-status"><span class="activity-spinner" aria-hidden="true"></span><span class="status-dot" aria-hidden="true"></span><p id="status" role="status" aria-live="polite">{{if .Offline}}Saved inventory · Read-only{{else}}Ready when you are. No scan started.{{end}}</p></div><section id="tcp-activity" class="tcp-activity" hidden role="status" aria-live="polite"><span class="tcp-activity-icon" aria-hidden="true"></span><div><strong id="tcp-activity-host"></strong><span id="tcp-activity-label"></span><progress aria-label="TCP inspection in progress"></progress></div></section><section id="monitor-progress" class="monitor-progress" hidden aria-label="Discovery progress"><div class="countdown"><strong id="discovery-countdown">00:30</strong><span id="countdown-label">Next discovery</span></div><div class="monitor-summary"><span id="window-notice" role="status" aria-live="polite"></span><progress id="discovery-meter" max="100" value="0" aria-label="Discovery timer"></progress><p id="tcp-progress" role="status"></p></div></section><details class="scan-alerts"><summary id="warnings-summary" hidden>Scan notes</summary><ul id="warnings" class="scan-warnings"></ul></details>
</section></header>
<div class="workspace-layout"><section class="inventory-panel" aria-label="Device inventory"><div class="inventory-heading"><div><span class="eyebrow">DEVICE EXPLORER</span><h2>Network inventory</h2></div><span class="memory-badge">{{if .Offline}}Saved inventory{{else}}In memory{{end}}</span></div>

<div class="snapshot-toolbar"><a class="btn btn-sm btn-outline-primary" data-save-snapshot href="/api/snapshots/export" download>Save results</a><button type="button" class="btn btn-sm btn-outline-secondary" data-load-snapshot>Load results</button><input type="file" id="snapshot-file" accept=".json,application/json" hidden><button class="btn btn-sm btn-outline-secondary" id="snapshot-live" type="button">Live inventory</button><span id="snapshot-note" role="status">{{if .Offline}}Saved inventory · Read-only{{end}}</span></div><div id="devices" hx-get="/devices" hx-trigger="inventory-changed from:body" hx-swap="innerHTML">{{template "devices" .}}</div></section></div>
<dialog id="json-dialog" aria-labelledby="json-title"><div class="json-dialog-heading"><h2 id="json-title">Device JSON</h2><button type="button" class="btn btn-sm btn-outline-danger" data-json-close aria-label="Close JSON">Close</button></div><p id="json-status" role="status"></p><pre id="json-content"></pre></dialog><dialog id="services-dialog" aria-labelledby="services-title"><div class="json-dialog-heading"><h2 id="services-title">TCP services</h2><button type="button" class="btn btn-sm btn-outline-danger" data-services-close>Close</button></div><div class="services-toolbar"><input type="search" class="form-control" id="services-search" placeholder="Search ports, services, CVEs…" aria-label="Search TCP services"><select id="services-state" class="form-select" aria-label="Port state"><option value="">All states</option><option value="open">Open</option><option value="filtered">Filtered</option><option value="closed">Closed</option><option value="references">With references</option></select></div><div id="services-status" role="status"></div><div id="services-content"></div><nav class="services-pagination" aria-label="TCP service pages"><button type="button" class="btn btn-sm btn-outline-secondary" id="services-prev">Previous</button><span id="services-page"></span><button type="button" class="btn btn-sm btn-outline-secondary" id="services-next">Next</button></nav></dialog><dialog id="shares-dialog" aria-labelledby="shares-title"><div class="json-dialog-heading"><h2 id="shares-title">Shared folders</h2><button type="button" class="btn btn-sm btn-outline-danger" data-shares-close>Close</button></div><p id="shares-status" role="status"></p><progress id="shares-progress" hidden aria-label="Shared folder request in progress"></progress><div class="check-controls"><button type="button" id="shares-start" class="btn btn-primary" hidden>Stop discovery &amp; list folders</button><button type="button" id="shares-cancel" class="btn btn-outline-danger" disabled>Cancel request</button></div><div id="shares-content"></div></dialog><dialog id="check-dialog" aria-labelledby="check-title"><div class="json-dialog-heading"><h2 id="check-title">Service check</h2><button type="button" class="btn btn-sm btn-outline-danger" data-check-close>Close</button></div><p id="check-note"></p><div id="check-progress" role="status" aria-live="polite"></div><progress id="check-meter" hidden aria-label="Service check in progress"></progress><div id="check-verdict" role="status" aria-live="polite" hidden></div><div id="check-result"></div><div class="check-controls"><button type="button" class="btn btn-sm btn-primary" id="check-start">Run check</button><button type="button" class="btn btn-sm btn-outline-danger" id="check-cancel" disabled>Cancel</button></div></dialog><dialog id="windows-dialog" aria-labelledby="windows-title"><div class="json-dialog-heading"><h2 id="windows-title">Windows assessment</h2><button type="button" class="btn btn-sm btn-outline-danger" data-windows-close>Close</button></div><p>Run the Windows collector and import its results directly from this host.</p><label for="windows-user">Windows account</label><input id="windows-user" class="form-control" maxlength="64" value="Administrator" autocomplete="username"><button id="windows-ssh" type="button" class="btn btn-primary">Run assessment</button><small id="windows-access">Requires configured SSH key access and trusted host identity.</small><details class="service-evidence"><summary>Manual export / import</summary><a href="/api/windows/collector" download class="btn btn-sm btn-outline-primary">Download collector</a><label class="btn btn-sm btn-outline-primary">Import JSON<input id="windows-file" type="file" accept="application/json,.json" hidden></label></details><p id="windows-status" role="status"></p><div id="windows-results"></div></dialog><footer class="workspace-footer"><span>NetExplorer · Built for your authorized LAN</span><nav aria-label="Application APIs"><a href="/api/health">Health</a><a href="/api/interfaces">Interfaces</a><a href="/api/devices">Inventory JSON</a></nav></footer></main></body></html>`

// devicesTemplate renders a display-only catalog while preserving escaped evidence.
const devicesTemplate = `{{define "devices"}}{{$view := inventoryView .Devices .Hosts}}{{$nmapAvailable := .NmapAvailable}}{{$offline := .Offline}}<div class="inventory-stats" aria-label="Inventory totals and views">
<button type="button" class="stat" data-inventory-filter="hosts" aria-pressed="false" title="One card per remote IP"><span class="stat-label">REMOTE HOSTS</span><strong>{{$view.Hosts}}</strong></button>
<button type="button" class="stat" data-inventory-filter="devices" aria-pressed="false" title="Show identified UPnP devices"><span class="stat-label">LOGICAL DEVICES</span><strong>{{$view.Devices}}</strong></button>
<button type="button" class="stat" data-inventory-filter="services" aria-pressed="false" title="Show devices with UPnP or open TCP services"><span class="stat-label">SERVICES</span><strong>{{$view.Services}}</strong></button>
<button type="button" class="stat" data-inventory-filter="manufacturers" aria-pressed="false" title="Devices with identified manufacturers"><span class="stat-label">MANUFACTURERS</span><strong>{{$view.Manufacturers}}</strong></button></div>
<div class="inventory-toolbar"><label class="search-box"><span class="visually-hidden">Search name, IP, model or manufacturer</span><input type="search" class="form-control" data-inventory-search placeholder="Search devices or IP…" autocomplete="off"></label><label><span class="visually-hidden">Manufacturer</span><select class="form-select" data-inventory-vendor aria-label="Manufacturer"><option value="">All manufacturers</option></select></label><button type="button" class="btn btn-sm btn-outline-secondary" data-inventory-reset>All</button></div>
<div class="inventory-results" role="status" aria-live="polite"></div>
<div class="device-grid">{{range $view.Cards}}<article class="device-card kind-{{.KindClass}}" id="device-{{.ID}}" data-kind="{{.Kind}}" data-ip="{{.IP}}" data-parent="{{.ParentID}}" data-host="{{.IsHost}}" data-logical="{{if .Identities}}true{{else}}false{{end}}" data-services="{{len .Services}}" data-tcp="{{.TCPServices}}" data-vendor="{{if ne .Vendor "Unknown manufacturer"}}{{.Vendor}}{{end}}"><div class="device-card-top">{{if ne .Title .Kind}}<span class="kind-badge">{{.Kind}}</span>{{end}}{{if .ParentID}}<span class="embedded-badge" title="Logical device embedded in a parent description">Embedded</span>{{end}}</div>
<div class="device-identity"><div class="device-art" aria-hidden="true"><svg><use href="/static/icons/devices.svg#{{.KindIcon}}"></use></svg></div><div class="device-heading"><h3>{{.Title}}</h3>{{if and (ne .Model "Model not advertised") (not .IsHost)}}<p class="device-model">{{.Model}}</p>{{end}}</div></div><div class="host-address"><span class="ip-label">{{if .IP}}{{.IP}}{{else}}IP not available{{end}}</span>{{if .MACLabel}}<span aria-hidden="true">·</span>{{if .MACVendorURL}}<a class="mac-label" href="{{.MACVendorURL}}" target="_blank" rel="noopener noreferrer" title="Look up vendor on MacVendors (sends this MAC to an external service)">{{.MACLabel}} ↗</a>{{else}}<span class="mac-label" title="Observed MAC address">{{.MACLabel}}</span>{{end}}{{if .MACLocal}}<span class="mac-private" tabindex="0" role="img" aria-label="Locally administered MAC; possibly randomized" title="Locally administered MAC; possibly randomized. The prefix does not identify a manufacturer.">🔒</span>{{end}}{{end}}</div>
<div class="vendor-row">{{if eq .Vendor "Unknown manufacturer"}}<span class="missing-icon" tabindex="0" role="img" aria-label="Manufacturer not advertised" title="Manufacturer not advertised"><svg aria-hidden="true"><use href="/static/icons/devices.svg#network"></use></svg><span aria-hidden="true">?</span></span>{{else}}{{if .VendorLogo}}<div class="vendor-mark"><img src="{{.VendorLogo}}" width="84" height="32" alt="{{.Vendor}} logo" loading="lazy"></div>{{end}}<span class="vendor-label" title="{{if or .IsHost .VendorRegistry}}MAC registry vendor; not verified device brand{{else}}{{if .VendorInherited}}From parent description{{else}}Advertised manufacturer{{end}}{{end}}">{{.Vendor}}</span>{{end}}</div>
<div class="card-facts"><div class="card-tabs" role="tablist" aria-label="Device details">
<button type="button" role="tab" id="tab-services-{{.ID}}" aria-controls="panel-services-{{.ID}}" aria-selected="false" data-card-tab="services">Services <span>{{len .Services}}</span></button>
<button type="button" role="tab" id="tab-tcp-{{.ID}}" aria-controls="panel-tcp-{{.ID}}" aria-selected="false" tabindex="-1" data-card-tab="tcp">TCP ports <span>{{if .Host.EnrichedAt.IsZero}}—{{else}}{{len .Host.Ports}}{{end}}</span></button>
<button type="button" role="tab" id="tab-identity-{{.ID}}" aria-controls="panel-identity-{{.ID}}" aria-selected="false" tabindex="-1" data-card-tab="identity">Identity</button></div><section class="card-tab-panel service-section" role="tabpanel" id="panel-services-{{.ID}}" aria-labelledby="tab-services-{{.ID}}" data-card-panel="services" tabindex="0" hidden><div class="service-chips">{{range .Services}}<span class="service-chip" title="{{.Type}}">{{serviceName .Type}}</span>{{else}}<span class="no-services">No advertised services.</span>{{end}}</div></section>
<section class="card-tab-panel nmap-results" role="tabpanel" id="panel-tcp-{{.ID}}" aria-labelledby="tab-tcp-{{.ID}}" data-card-panel="tcp" tabindex="0" hidden><div class="port-list">{{$card := .}}{{range portPreview .Host}}<div class="port-row">{{if .WebURL}}<a class="port-number" href="{{.WebURL}}" target="_blank" rel="noopener noreferrer" title="Open web service">{{.Number}}/{{.Protocol}} ↗</a>{{else}}{{if .MediaURL}}<a class="port-number" href="{{mediaLink .MediaURL}}" title="Open in an RTSP client (for example VLC)">{{.Number}}/{{.Protocol}} ↗</a>{{else}}{{if eq .Action "rdp"}}<button class="port-number endpoint-rdp" type="button" data-rdp-ip="{{$card.IP}}" data-rdp-host="{{$card.Host.ID}}" data-rdp-port="{{.Number}}" title="Download RDP connection">{{.Number}}/{{.Protocol}} ↗</button>{{else}}<span class="port-number">{{.Number}}/{{.Protocol}}</span>{{end}}{{end}}{{end}}<span class="port-state state-{{.State}}" tabindex="0" role="img" aria-label="{{.State}}" title="{{.State}}">{{stateIcon .State}}</span><span class="port-service">{{.Service}}{{with .Product}} · {{.}}{{end}}{{with .Version}} {{.}}{{end}}{{if .History}} <span class="reference-mark" title="Historical port association; not proof of infection" aria-label="Historical port association">⚑</span>{{end}}{{if .CVEs}} <span class="reference-mark" title="Potential CVE version match; applicability unverified" aria-label="Potential CVE version match">⚠</span>{{end}}</span></div>{{else}}<p class="no-services">No individual port results returned.</p>{{end}}</div><button type="button" class="btn btn-sm btn-outline-primary" data-services-host="{{.Host.ID}}">All TCP services ↗</button></section>
<section class="card-tab-panel device-details" role="tabpanel" id="panel-identity-{{.ID}}" aria-labelledby="tab-identity-{{.ID}}" data-card-panel="identity" tabindex="0" hidden><div class="detail-content"><dl>{{if .IsHost}}<dt>Host IP</dt><dd>{{.IP}}</dd>{{with .MACLabel}}<dt>Observed MAC</dt><dd>{{.}}</dd>{{end}}{{with .Host.MDNS}}<dt>mDNS hints · unverified</dt><dd>{{range .}}<div>{{.}}</div>{{end}}</dd>{{end}}<dt>Sources</dt><dd>{{range .Host.Sources}}{{.}} {{end}}</dd>{{else}}<dt>UDN</dt><dd>{{.UDN}}</dd>{{end}}{{with .Host.Vendor}}<dt>MAC registry vendor</dt><dd>{{.}}</dd>{{end}}<dt>Device type</dt><dd>{{index .Attributes "device_type"}}</dd>{{if .ParentID}}<dt>Parent device</dt><dd><a href="#device-{{.ParentID}}">{{.ParentID}}</a></dd>{{end}}{{with index .Attributes "manufacturer"}}<dt>Reported manufacturer</dt><dd>{{.}}</dd>{{end}}</dl>{{if gt (len .Identities) 1}}<details class="identity-evidence"><summary>UPnP identities · {{len .Identities}}</summary><dl>{{range .Identities}}<dt>{{serviceName (index .Attributes "device_type")}}</dt><dd>{{with index .Attributes "friendly_name"}}{{.}}<br>{{end}}<a data-json-popup href="/api/devices/{{.ID}}">Device JSON ↗</a></dd>{{end}}</dl></details>{{end}}<details class="identity-evidence"><summary>Evidence</summary><dl>{{range $field,$items := .Evidence}}<dt>{{$field}}</dt>{{range $items}}<dd><strong>{{.Source}}</strong>: {{.Value}}<br><small>{{.ObservedAt}} · {{.Location}}</small></dd>{{end}}{{end}}</dl></details></div></section>
</div>{{if .OSLabel}}<span class="auto-tcp-badge" title="{{.OSSource}}">{{.OSLabel}}</span>{{end}}{{with .Host.AutoTCPStatus}}<span class="auto-tcp-badge" data-tcp-status="{{.}}">TCP · {{.}}</span>{{end}}<div class="nmap-action"><select class="form-select tcp-profile" aria-label="TCP inspection coverage"><option value="common">Common + notable</option><option value="full">All 65,535 TCP ports</option></select><button class="btn btn-sm btn-outline-primary nmap-button" type="button" data-nmap-host="{{.Host.ID}}" data-nmap-ip="{{.IP}}" title="Inspect TCP services on this IP only" {{if not $nmapAvailable}}disabled title="Nmap unavailable on PATH"{{end}}>Inspect TCP</button></div>
{{if and $offline .Host.WindowsCaption}}<a data-json-popup href="/api/snapshots/windows/{{.Host.ID}}">Windows report JSON ↗</a>{{end}}{{if and .IsWindows (not $offline)}}<button type="button" class="btn btn-sm btn-outline-secondary" data-windows-host="{{.Host.ID}}" data-windows-ip="{{.IP}}">Windows assessment</button>{{end}}<div class="device-card-footer"><span class="source-label">{{if .IsHost}}{{range .Host.Sources}}{{.}} {{end}}{{else}}SSDP{{if index .Attributes "device_type"}} + UPnP{{end}}{{end}}</span>{{if .IsHost}}<a data-json-popup href="/api/hosts/{{.Host.ID}}">Host JSON <span aria-hidden="true">↗</span></a>{{else}}<a data-json-popup href="/api/devices/{{.ID}}">Device JSON <span aria-hidden="true">↗</span></a>{{end}}</div></article>{{else}}<div class="inventory-empty"><div class="empty-art"><svg aria-hidden="true"><use href="/static/icons/devices.svg#network"></use></svg></div><h3>No devices yet</h3><p>Choose a network and start a scan.</p></div>{{end}}</div><p class="filter-empty" hidden>No matches. Try another filter or search.</p><nav class="inventory-pagination" aria-label="Inventory pages"><button type="button" class="btn btn-sm btn-outline-secondary" data-page-prev>Previous</button><span data-page-label></span><button type="button" class="btn btn-sm btn-outline-secondary" data-page-next>Next</button><label><span class="visually-hidden">Items per page</span><select data-page-size class="form-select" aria-label="Items per page"><option value="12">12 / page</option><option value="24">24 / page</option><option value="48">48 / page</option></select></label></nav>{{end}}`
